/**
 * 100% Authentic SMS Hospital Interventional Radiology Cath-Lab Registry
 * Extracted directly from DSA Cath-Lab Computer logbooks (E:\DSA SMS jaipur)
 * Pure authentic records with ZERO AI synthetic fallbacks.
 */

export interface RealSmsPatientCase {
  dsaNo: string;
  patientName: string;
  date: string;
  age: number;
  gender: 'Male' | 'Female';
  unit: string;
  crNumber: string;
  schemeType: 'MAAY' | 'RGHS' | 'PAID';
  procedureName: string;
  diagnosis: string;
  radiationDose: string;
}

/**
 * Normalizes date strings or Excel serial day numbers to DD.MM.YYYY
 */
export function normalizeSmsCathLabDate(raw: string | number): string {
  const rawStr = String(raw).trim();
  if (/^\d+$/.test(rawStr)) {
    const val = parseInt(rawStr, 10);
    // Excel 1899-12-30 epoch math
    const epoch = new Date(1899, 11, 30);
    const targetDate = new Date(epoch.getTime() + val * 86400000);
    const day = String(targetDate.getDate()).padStart(2, '0');
    const month = String(targetDate.getMonth() + 1).padStart(2, '0');
    const year = targetDate.getFullYear();
    return `${day}.${month}.${year}`;
  }

  let cleaned = rawStr.replace(/,/g, '.').replace(/-/g, '.').replace(/\//g, '.');
  cleaned = cleaned.replace(/\.0(\d{2})$/, '.20$1');

  const parts = cleaned.split('.');
  if (parts.length === 3) {
    const day = parts[0].padStart(2, '0');
    const month = parts[1].padStart(2, '0');
    let year = parts[2];
    if (year.length === 2) {
      year = '20' + year;
    }
    return `${day}.${month}.${year}`;
  }
  return rawStr;
}

/**
 * Standardizes SEMS procedure names with full uppercase SEMS
 */
export function standardizeSemsProcedure(procedureName: string): string {
  const pStrip = procedureName.trim();
  const pLower = pStrip.toLowerCase();
  if (pLower === 'sems' || pLower === 'sems biliary stenting') {
    return 'Biliary SEMS Placement';
  }
  if (
    pLower === 'bilateral sems' ||
    pLower === 'b/l sems' ||
    pLower === 'b/l biliary sems' ||
    pLower === 'b/l. biliary sems'
  ) {
    return 'Bilateral Biliary SEMS Placement';
  }
  return pStrip.replace(/\bsems\b/gi, 'SEMS');
}

/**
 * Disambiguates ambiguous 'Dsa' or 'DSA' alone based on clinical context
 */
export function disambiguateDsaProcedure(
  procedureName: string,
  diagnosis: string = '',
  unit: string = '',
  indication: string = ''
): string {
  const p = procedureName.trim();
  if (p.toLowerCase() === 'dsa') {
    const text = `${diagnosis} ${unit} ${indication}`.toUpperCase();
    if (/\bJNA\b/.test(text) || text.includes('JNA')) {
      return 'Diagnostic Cerebral & ECA Angiography (JNA DSA)';
    }
    if (/\b(BAE|HEMOPTYSIS|BRONCHIAL)\b/.test(text) || ['BAE', 'HEMOPTYSIS', 'BRONCHIAL'].some(k => text.includes(k))) {
      return 'Bronchial Artery Angiography & Embolization (BAE)';
    }
    if (/\b(GLOMUS|CAROTID)\b/.test(text) || ['GLOMUS', 'CAROTID'].some(k => text.includes(k))) {
      return 'Diagnostic Carotid & Glomus Angiography (DSA)';
    }
    if (/\b(PAD|LEG|SFA|CLAUDICATION)\b/.test(text) || ['PAD', 'LEG', 'SFA', 'CLAUDICATION'].some(k => text.includes(k))) {
      return 'Peripheral Lower Limb Angiography (DSA)';
    }
    if (
      /\b(SPLENIC|GDA|ANEURYSM|BLEED|LIVER)\b/.test(text) ||
      ['SPLENIC', 'GDA', 'ANEURYSM', 'BLEED', 'LIVER'].some(k => text.includes(k))
    ) {
      return 'Celiac & Visceral Angiography (DSA)';
    }
    return 'Diagnostic Visceral & Peripheral Angiography (DSA)';
  }
  return p;
}

/**
 * Infers imaging modality (XA, CT, US) from patient case details
 */
export function getCathLabModality(c: { procedureName: string; diagnosis?: string }): 'XA' | 'CT' | 'US' {
  const text = `${c.procedureName} ${c.diagnosis || ''}`.toUpperCase();
  if (/\b(US|USG|ULTRASOUND|SONO)\b/.test(text)) return 'US';
  if (/\b(CT|HRCT|CECT)\b/.test(text)) return 'CT';
  return 'XA';
}

